@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#68e9ff;--red:#f54253;--white:#f1f5f8;--muted:#9aa8b6;--panel:rgba(7,15,25,.76)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#07111e;color:var(--white);font-family:Inter,Arial,sans-serif}#game{position:fixed;inset:0}#game canvas{display:block;width:100%;height:100%}.vignette{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 40%,rgba(1,7,15,.3) 100%),linear-gradient(180deg,rgba(4,11,21,.24),transparent 30%,transparent 76%,rgba(3,8,16,.48)}
.topbar{position:fixed;inset:0 0 auto;height:62px;padding:0 4.1vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(160,207,230,.12);background:linear-gradient(180deg,rgba(3,9,17,.62),transparent);z-index:3;font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.13em;color:#d9e3eb}.brand{display:flex;align-items:center;gap:11px}.brand-mark{font-size:20px;color:var(--cyan);text-shadow:0 0 15px #43caff}.brand b,.location b{color:var(--red)}.mission-tag{font-size:9px;color:#c5d5e0;display:flex;align-items:center;gap:9px}.mission-tag i,.pulse-dot{width:6px;height:6px;border-radius:50%;background:#ff4e5e;box-shadow:0 0 11px #ff4e5e;display:inline-block;animation:pulse 1.4s infinite}.icon-button{border:1px solid rgba(187,218,237,.25);background:rgba(6,17,28,.5);color:#eaf3f8;padding:9px 13px;font:10px 'DM Mono',monospace;letter-spacing:.08em}.icon-button span{font-size:9px;color:#93a5b2;margin-left:5px}
.hud{position:fixed;z-index:2;top:82px;left:4.1vw;right:4.1vw;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none;transition:opacity .3s}.hero-panel,.objective-panel{background:linear-gradient(110deg,rgba(3,12,22,.86),rgba(7,18,29,.68));border-left:2px solid rgba(75,216,255,.82);padding:13px 17px 14px;min-width:256px;box-shadow:0 8px 26px #02070c42}.hero-kicker,.objective-kicker{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#83dff5}.hero-name{font:700 22px 'Barlow Condensed',sans-serif;letter-spacing:.05em;margin:2px 0 10px}.hero-name>span{color:#607b8b}.hero-name small{font-size:10px;color:#8da0af;letter-spacing:.14em}.health-row,.web-row{display:flex;align-items:center;gap:9px;margin-top:6px}.health-label{font:8px 'DM Mono',monospace;color:#93a3b0;letter-spacing:.1em;width:60px}.health-row b,.web-row b{font:9px 'DM Mono',monospace;color:#e3edf2;width:24px;text-align:right}.health-track,.web-track,.progress-track{height:4px;flex:1;background:rgba(191,216,229,.16);overflow:hidden}.health-track>div{height:100%;width:100%;background:linear-gradient(90deg,#ff4858,#ff7c68);box-shadow:0 0 9px #fc344e;transition:width .25s}.web-track>div{height:100%;width:100%;background:#56ddf4;box-shadow:0 0 8px #48d8f6;transition:width .25s}.objective-panel{min-width:230px;border-left-color:#f04d61;margin:0 auto 0 20px;max-width:290px}.objective-kicker{color:#ff8490;display:flex;align-items:center;gap:8px}.objective-kicker .pulse-dot{width:5px;height:5px}.objective-panel #objective{font:600 16px 'Barlow Condensed',sans-serif;letter-spacing:.04em;margin:7px 0 9px}.objective-progress{display:flex;align-items:center;gap:9px;font:9px 'DM Mono',monospace;color:#b5c3cc}.progress-track{height:3px;width:98px;flex:initial}.progress-track>div{height:100%;width:0;background:#f04d61;transition:width .4s}.assist-panel{display:flex;align-items:center;gap:10px;background:rgba(6,15,24,.72);padding:10px 12px;border:1px solid rgba(194,219,232,.16);min-width:208px}.assist-icon{width:27px;height:27px;border:1px solid #ffc559;border-radius:50%;color:#ffc559;display:grid;place-items:center;font:800 16px 'Barlow Condensed';box-shadow:0 0 12px #fbaf3336}.assist-panel small{display:block;font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#f2c56a;margin-bottom:4px}.assist-panel b{font:9px 'DM Mono',monospace;letter-spacing:.04em}.assist-panel kbd{margin-left:7px;border-color:#ffc559;color:#ffc559}.assist-meter{position:absolute;height:2px;bottom:-1px;left:0;right:0;background:#ffffff1a}.assist-meter i{display:block;background:#ffc559;height:100%;width:100%;transition:width .25s}
.bottom-hud{position:fixed;z-index:2;left:0;right:0;bottom:0;padding:14px 4.1vw 18px;display:flex;justify-content:space-between;align-items:flex-end;background:linear-gradient(0deg,rgba(3,8,15,.78),transparent);transition:opacity .3s}.controls{display:flex;gap:19px;align-items:center}.controls>span{display:flex;align-items:center;gap:3px}.controls label{font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#c1ced7;margin-left:6px}.controls kbd,kbd{font:9px 'DM Mono',monospace;color:#e9f4f8;border:1px solid rgba(208,231,241,.34);border-bottom-color:rgba(208,231,241,.68);border-radius:3px;padding:4px 5px;background:rgba(15,29,43,.75);min-width:21px;text-align:center}.location{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#b6c3ce}.location-pin{color:var(--cyan);font-size:16px;vertical-align:-2px;margin-right:6px}
.screen{position:fixed;inset:0;z-index:5;display:grid;place-items:center;background:rgba(3,9,17,.39);transition:opacity .55s,visibility .55s}.screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.screen-backdrop{position:absolute;inset:0;background:linear-gradient(90deg,rgba(2,7,14,.77) 0%,rgba(3,8,15,.55) 43%,rgba(3,8,15,.12) 100%),linear-gradient(0deg,rgba(3,8,15,.49),transparent 55%)}.intro-content,.end-content{position:relative;width:min(550px,90vw);margin:3vh 0 0 -35vw;animation:rise .75s both}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.22em;color:#9eb0bb;display:flex;align-items:center;gap:9px}.eyebrow span{display:inline-block;width:25px;height:1px;background:#67dff5}.intro-content h1,.end-content h2{font:900 clamp(72px,9vw,128px)/.79 'Barlow Condensed',Impact,sans-serif;letter-spacing:-.025em;margin:24px 0 16px;text-shadow:0 6px 45px #06111c}.intro-content h1 em,.end-content h2 em{font-style:normal;color:var(--red);text-shadow:0 0 35px #f3263b42}.title-rule{display:flex;align-items:center;gap:10px;color:#b2c2cc;font:9px 'DM Mono',monospace;letter-spacing:.14em}.title-rule span{height:1px;width:43px;background:#f05261}.title-rule span:last-child{width:84px;background:#73828d}.intro-content p,.end-content p{color:#c3ced7;font-size:13px;line-height:1.75;margin:21px 0 23px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:54px;padding:0 0 0 21px;height:48px;min-width:180px;border:0;background:#e83f53;color:white;font:700 11px 'DM Mono',monospace;letter-spacing:.13em;cursor:pointer;box-shadow:0 8px 27px #ed30443d;transition:.2s}.primary-button:hover{background:#ff5868;transform:translateY(-2px);box-shadow:0 11px 33px #ed304468}.primary-button b{height:48px;width:43px;background:#ffffff18;display:grid;place-items:center;font-size:19px}.start-note{margin-top:15px;color:#8496a3;font:8px 'DM Mono',monospace;letter-spacing:.13em}.start-note span{color:#fa5363;padding:0 5px}.intro-side-note{position:absolute;right:4.2vw;bottom:7vh;writing-mode:vertical-rl;font:8px 'DM Mono',monospace;letter-spacing:.2em;color:#a6b8c2}.intro-side-note span{color:#5e7481;margin-top:12px}.intro-version{position:absolute;right:4.2vw;top:50%;font:9px 'DM Mono',monospace;color:#8999a4;letter-spacing:.15em}.end-content{margin:0 0 0 -28vw}.end-content h2{font-size:clamp(58px,7vw,100px)}.end-content p{font-size:14px}
.reticle{position:fixed;z-index:2;left:50%;top:50%;width:22px;height:22px;margin:-11px;opacity:0;transition:opacity .3s;pointer-events:none}.reticle i{position:absolute;inset:2px;border:1px solid #dcf8ff;border-radius:50%;box-shadow:0 0 10px #43dfff}.reticle b{position:absolute;left:10px;top:-3px;height:26px;width:1px;background:#dcf8ff7a}.reticle:after{content:'';position:absolute;left:-3px;top:10px;width:26px;height:1px;background:#dcf8ff7a}body.playing .reticle{opacity:.55}.swing-hint{position:fixed;z-index:2;left:50%;top:57%;transform:translateX(-50%);font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#c9f8ff;text-shadow:0 0 9px #00d9ff;opacity:0;transition:opacity .2s}.swing-hint.visible{opacity:1}.swing-hint span{border:1px solid #b9f4ff;padding:3px 6px;margin-left:7px}.toast{position:fixed;z-index:4;left:50%;top:25%;transform:translate(-50%,-10px);font:700 16px 'Barlow Condensed',sans-serif;letter-spacing:.13em;color:#d5faff;text-shadow:0 0 15px #00cfff;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.damage-flash{position:fixed;inset:0;z-index:2;pointer-events:none;border:0 solid rgba(246,42,66,0);transition:border .15s}.damage-flash.hit{border:9px solid rgba(246,42,66,.42)}.boss-alert{position:fixed;z-index:3;top:32%;left:50%;transform:translate(-50%,-10px);opacity:0;padding:11px 18px;border-top:1px solid #f44d5d;border-bottom:1px solid #f44d5d;background:#150c17aa;color:#ffc1c8;font:10px 'DM Mono',monospace;letter-spacing:.13em;transition:.4s;pointer-events:none}.boss-alert.visible{opacity:1;transform:translate(-50%,0)}.boss-alert span{color:#ff4d5f;font-size:14px;margin-right:9px}.loading{position:fixed;inset:0;z-index:10;display:flex;gap:12px;align-items:center;justify-content:center;background:#07111e;color:#b6eefa;font:9px 'DM Mono',monospace;letter-spacing:.16em;transition:opacity .4s}.loading.done{opacity:0;pointer-events:none}.loader-orbit{width:17px;height:17px;border-radius:50%;border:1px solid #3c6171;border-top-color:#6fe6ff;animation:spin .7s linear infinite}
@keyframes pulse{50%{opacity:.35;box-shadow:0 0 3px #ff4e5e}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:750px){.topbar{padding:0 18px}.mission-tag{display:none}.hud{top:72px;left:15px;right:15px;flex-wrap:wrap;gap:8px}.hero-panel{min-width:205px;padding:10px 12px}.objective-panel{margin:0;min-width:180px;padding:10px 12px;max-width:220px}.assist-panel{display:none}.hero-name{font-size:18px}.bottom-hud{padding:11px 15px 14px;display:block}.controls{gap:7px;justify-content:center}.controls>span{gap:2px}.controls label{display:none}.controls kbd{font-size:8px;min-width:19px;padding:4px}.location{margin-top:10px;text-align:center;font-size:8px}.intro-content{margin:0 0 0 -13vw;width:85vw}.intro-content h1{font-size:clamp(67px,17vw,105px)}.intro-content p{font-size:12px}.intro-side-note,.intro-version{display:none}.end-content{margin:0;width:85vw}.icon-button span{display:none}}@media(max-height:600px){.intro-content{transform:scale(.82);transform-origin:left center}.hud{top:70px}.bottom-hud{padding-bottom:10px}}

import * as THREE from 'three';

const mount = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101e31);
scene.fog = new THREE.FogExp2(0x101e31, 0.0065);
const camera = new THREE.PerspectiveCamera(63, innerWidth / innerHeight, 0.1, 420);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
mount.appendChild(renderer.domElement);

const clock = new THREE.Clock();
const ui = Object.fromEntries(['intro-screen','end-screen','start-button','restart-button','end-title','end-copy','health-fill','health-value','web-fill','web-value','objective','progress-count','progress-fill','assist-fill','assist-text','toast','damage-flash','swing-hint','boss-alert','loading','audio-toggle'].map(id => [id, document.getElementById(id)]));
const clamp = THREE.MathUtils.clamp;
const rand = (a,b) => a + Math.random() * (b-a);
const mats = {};
const material = (name, color, roughness=.8, extra={}) => mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const boxGeo = new THREE.BoxGeometry(1,1,1);
const sphereGeo = new THREE.SphereGeometry(1,18,12);
const cylinderGeo = new THREE.CylinderGeometry(1,1,1,10);

scene.add(new THREE.HemisphereLight(0xb4dcff, 0x141d2e, 1.15));
const moon = new THREE.DirectionalLight(0xd0e9ff, 2.15);
moon.position.set(-35, 55, -28); moon.castShadow = true;
moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-55; moon.shadow.camera.right=55; moon.shadow.camera.top=55; moon.shadow.camera.bottom=-55;
moon.shadow.bias = -0.0003; scene.add(moon);
const cityGlow = new THREE.PointLight(0x1d7dd1, 100, 105, 2); cityGlow.position.set(-8,18,5); scene.add(cityGlow);
const redGlow = new THREE.PointLight(0xf1425c, 62, 62, 2); redGlow.position.set(17,11,-14); scene.add(redGlow);

const ground = new THREE.Mesh(new THREE.PlaneGeometry(320,320), material('asphalt',0x111a26,.95));
ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; ground.position.y=-.12; scene.add(ground);
const grid = new THREE.GridHelper(180,72,0x1d3850,0x182737); grid.position.y=-.105; grid.material.transparent=true; grid.material.opacity=.19; scene.add(grid);
function addBox(parent, geo, mat, pos, scale, cast=false, receive=false) { const m=new THREE.Mesh(geo,mat); m.position.set(...pos); m.scale.set(...scale); m.castShadow=cast; m.receiveShadow=receive; parent.add(m); return m; }
function addStreetMarkings(){
  const white=material('roadPaint',0x8293a1,.72,{emissive:0x101b23,emissiveIntensity:.3});
  for(let i=-5;i<=5;i++){
    addBox(scene,boxGeo,white,[i*3.5,.008,0],[.075,.012,66]);
    addBox(scene,boxGeo,white,[0,.009,i*3.5],[66,.012,.075]);
  }
  for(const z of [-18,18]) for(let i=-5;i<=5;i++) addBox(scene,boxGeo,material('crosswalk',0x9caab3,.8),[i*1.35,.018,z],[.65,.018,3.8]);
  for(const x of [-18,18]) for(let i=-5;i<=5;i++) addBox(scene,boxGeo,material('crosswalk2',0x9caab3,.8),[x,.018,i*1.35],[3.8,.018,.65]);
  const curb=material('curb',0x46525c,.9);
  for(const edge of [-37,37]){addBox(scene,boxGeo,curb,[edge,.14,0],[1,.3,76],false,true);addBox(scene,boxGeo,curb,[0,.14,edge],[76,.3,1],false,true)}
  for(const z of [-29,29]) for(const x of [-34,34]){
    const pole=new THREE.Group(); pole.position.set(x,0,z);scene.add(pole);
    addBox(pole,cylinderGeo,material('lampPole',0x283543,.55),[0,3.6,0],[.075,7.2,.075]);
    addBox(pole,boxGeo,material('lampHead',0xa5dfff,.28,{emissive:0x63cfff,emissiveIntensity:2}),[0,7.15,0],[.62,.12,.24]);
    const l=new THREE.PointLight(0x6acfff,22,17,2);l.position.set(0,6.8,0);pole.add(l);
  }
}
addStreetMarkings();

// A dense skyline ring keeps the fight readable while making the block feel enormous.
const windowInstances=[];
const windowGeo=new THREE.BoxGeometry(.4,.62,.08);
const windowMats=[0x23506a,0x8e7946,0x273b57,0x355d70,0x161f33].map((c,i)=>material('window'+i,c,.35,{emissive:c,emissiveIntensity:.5}));
const buildingColors=[0x243044,0x303b4c,0x1d293b,0x3a3945,0x202c3c,0x344354];
function makeBuilding(x,z,w,d,h,idx){
  const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);
  const bodymat=material('building'+idx,buildingColors[idx%buildingColors.length],.92);
  const body=addBox(group,boxGeo,bodymat,[0,h/2,0],[w,h,d],true,true);
  const cap=addBox(group,boxGeo,material('roof'+idx,0x465363,.8),[0,h+.14,0],[w+.28,.28,d+.28],false,true);
  if(idx%4===0){addBox(group,boxGeo,material('neonRed',0xe54158,.35,{emissive:0x8f1429,emissiveIntensity:1.6}),[0,h*.66,d/2+.03],[w*.74,.28,.08]);}
  if(idx%5===1){addBox(group,boxGeo,material('neonBlue',0x62dfff,.3,{emissive:0x239ac8,emissiveIntensity:1.3}),[w/2+.03,h*.45,0],[.08,.24,d*.68]);}
  // Art-deco crown and roof equipment break up silhouettes.
  if(idx%3===0){addBox(group,boxGeo,bodymat,[0,h+.7,0],[w*.42,1.1,d*.4]);addBox(group,cylinderGeo,material('antenna',0x8a9ba8,.5),[0,h+2.3,0],[.08,3.2,.08]);}
  const cols=Math.max(2,Math.floor(w/2.1)), rows=Math.min(17,Math.floor(h/2.4));
  for(let row=1;row<rows;row++) for(let col=0;col<cols;col++){
    const wx=-w/2+(col+.5)*w/cols;
    if(Math.random()>.48) windowInstances.push({pos:[x+wx,1+row*2.15,z+d/2+.052],color:Math.floor(Math.random()*windowMats.length),scale:[.38,.58,.055]});
    if(Math.random()>.66) windowInstances.push({pos:[x-w/2-.052,1+row*2.15,z-d/2+(col+.5)*d/cols],color:Math.floor(Math.random()*windowMats.length),scale:[.055,.58,.38]});
  }
  // Rooftop tanks
  if(idx%2===0){const tank=addBox(group,cylinderGeo,material('tank',0x6b7783,.65),[rand(-w*.24,w*.24),h+.75,rand(-d*.2,d*.2)],[1.3,1.5,1.3],false,true);tank.rotation.z=Math.PI/2;}
}
let bi=0;
for(let v=-57;v<=57;v+=13){
  for(const s of [-1,1]){
    const w=rand(8,12), d=rand(8,12), h=rand(22,54);
    makeBuilding(v,s*rand(43,54),w,d,h,bi++);
    const w2=rand(8,12),d2=rand(8,12),h2=rand(20,48);
    makeBuilding(s*rand(43,54),v,w2,d2,h2,bi++);
  }
}
for(let i=0;i<windowMats.length;i++){
  const inst=new THREE.InstancedMesh(windowGeo,windowMats[i],windowInstances.length); const dummy=new THREE.Object3D();let n=0;
  for(const win of windowInstances) if(win.color===i){dummy.position.set(...win.pos);dummy.scale.set(...win.scale);dummy.updateMatrix();inst.setMatrixAt(n++,dummy.matrix)}
  inst.count=n;inst.instanceMatrix.needsUpdate=true;scene.add(inst);
}
// Floating ash and city motes.
const moteGeo=new THREE.BufferGeometry(), motePositions=[];
for(let i=0;i<170;i++) motePositions.push(rand(-55,55),rand(1,22),rand(-55,55));
moteGeo.setAttribute('position',new THREE.Float32BufferAttribute(motePositions,3));
const motes=new THREE.Points(moteGeo,new THREE.PointsMaterial({color:0x8fdfff,size:.11,transparent:true,opacity:.48}));scene.add(motes);

function makeWebLine(color=0xe6fcff){
  const geo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3()]);
  const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.9}));scene.add(line);return line;
}
function updateLine(line,a,b){line.geometry.attributes.position.setXYZ(0,a.x,a.y,a.z);line.geometry.attributes.position.setXYZ(1,b.x,b.y,b.z);line.geometry.attributes.position.needsUpdate=true;line.geometry.computeBoundingSphere()}

const hero=new THREE.Group();scene.add(hero);
const rig=new THREE.Group();hero.add(rig);
const redSuit=material('suitRed',0xd62d43,.48,{metalness:.08});
const blueSuit=material('suitBlue',0x173b6d,.52,{metalness:.12});
const darkSuit=material('suitDark',0x0c2036,.57);
const webMat=material('suitWeb',0xf3e9e5,.45,{metalness:.15});
const eyeMat=material('eyeLens',0xf1fbff,.22,{emissive:0x84eaff,emissiveIntensity:.25});
function segment(parent,a,b,r1,r2,mat){const d=new THREE.Vector3(...b).sub(new THREE.Vector3(...a));const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),10),mat);mesh.position.copy(new THREE.Vector3(...a).add(new THREE.Vector3(...b)).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh}
// Hero body is assembled from original low-poly suit geometry.
const pelvis=addBox(rig,boxGeo,blueSuit,[0,1.08,0],[.49,.42,.3],true,true);pelvis.rotation.x=-.04;
const torso=addBox(rig,boxGeo,redSuit,[0,1.58,0],[.64,.72,.34],true,true);torso.rotation.x=-.035;
const chest=addBox(rig,boxGeo,blueSuit,[0,1.42,.176],[.38,.52,.045]);
const neck=new THREE.Mesh(new THREE.CylinderGeometry(.13,.16,.17,10),redSuit);neck.position.y=1.98;neck.castShadow=true;rig.add(neck);
const head=new THREE.Mesh(new THREE.SphereGeometry(.31,16,12),redSuit);head.scale.set(.9,1.12,.88);head.position.set(0,2.28,0);head.castShadow=true;rig.add(head);
// Stylized expressive eye lenses on the front of the mask.
for(const side of [-1,1]){
  const eye=new THREE.Mesh(new THREE.SphereGeometry(.105,12,8),eyeMat);eye.scale.set(.7,1.5,.24);eye.position.set(side*.13,2.31,.251);eye.rotation.z=side*-.22;rig.add(eye);
  const shoulder=new THREE.Mesh(new THREE.SphereGeometry(.21,12,9),redSuit);shoulder.scale.set(1,.8,1);shoulder.position.set(side*.39,1.78,0);shoulder.castShadow=true;rig.add(shoulder);
  segment(rig,[side*.4,1.72,0],[side*.48,1.32,.02],.12,.09,blueSuit);
  segment(rig,[side*.48,1.32,.02],[side*.46,.95,.1],.09,.075,redSuit);
  const glove=new THREE.Mesh(new THREE.SphereGeometry(.09,10,8),redSuit);glove.position.set(side*.46,.91,.12);glove.castShadow=true;rig.add(glove);
