const enemies=[];const webs=[];const keys={};
let started=false,ended=false,kills=0,total=8,spawned=0,spawnTimer=0,assistCooldown=0,toastTimer=0,damageTimer=0,camYaw=0,camPitch=.22,dragging=false,lastPointer={x:0,y:0};
const audio={ctx:null,on:true};
function sound(freq=360,duration=.08,type='sine',volume=.035){if(!audio.on)return;try{audio.ctx??=new AudioContext();const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.45),audio.ctx.currentTime+duration);g.gain.setValueAtTime(volume,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+duration);o.connect(g);g.connect(audio.ctx.destination);o.start();o.stop(audio.ctx.currentTime+duration)}catch{}}
function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.65}
function makeEnemy(boss=false){
  const g=new THREE.Group();const core=material('alienCore'+enemies.length,boss?0x342438:0x2d3747,.32,{metalness:.58,emissive:boss?0x541326:0x122b44,emissiveIntensity:.75});
  const shell=material('alienShell'+enemies.length,boss?0x6d2535:0x566270,.38,{metalness:.72});
  const redEye=material('alienEye',0xff4557,.2,{emissive:0xff1839,emissiveIntensity:3});
  const body=new THREE.Mesh(new THREE.IcosahedronGeometry(boss?1.05:.75,boss?1:0),core);body.position.y=boss?1.25:1.05;body.castShadow=true;g.add(body);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(boss?1.2:.88,.085,6,18),shell);ring.position.y=boss?1.22:1.02;ring.rotation.x=Math.PI/2.5;g.add(ring);
  const eye=new THREE.Mesh(new THREE.SphereGeometry(boss?.22:.15,10,8),redEye);eye.position.set(0,boss?1.3:1.1,.69);g.add(eye);
  for(let i=0;i<4;i++){const a=i*Math.PI/2;const p1=[Math.cos(a)*.5,.85,Math.sin(a)*.5],p2=[Math.cos(a)*.95,.3,Math.sin(a)*.95],p3=[Math.cos(a)*1.12,.12,Math.sin(a)*1.12];segment(g,p1,p2,.12,.075,shell);segment(g,p2,p3,.075,.045,core)}
  const orb=new THREE.PointLight(0xff293f,boss?20:8,5,2);orb.position.set(0,1.2,.4);g.add(orb);
  g.userData={hp:boss?4:2,maxHp:boss?4:2,boss,attack:rand(.8,2),phase:rand(0,6),hitFlash:0};
  const angle=rand(0,Math.PI*2),dist=rand(14,26);g.position.set(Math.cos(angle)*dist,0,Math.sin(angle)*dist);scene.add(g);enemies.push(g);spawned++;
  if(boss){ui['boss-alert'].classList.add('visible');setTimeout(()=>ui['boss-alert'].classList.remove('visible'),2800);announce('CHITAURI COMMANDER — TAKE IT DOWN');}
}
function updateHud(){ui['health-fill'].style.width=player.hp+'%';ui['health-value'].textContent=Math.ceil(player.hp);ui['web-fill'].style.width=player.web+'%';ui['web-value'].textContent=Math.ceil(player.web)+'%';ui['progress-count'].textContent=`${kills} / ${total}`;ui['progress-fill'].style.width=`${kills/total*100}%`;ui['assist-fill'].style.width=`${Math.max(0,(1-assistCooldown/28)*100)}%`;ui['assist-text'].innerHTML=assistCooldown>0?`RECHARGING <kbd>${Math.ceil(assistCooldown)}s</kbd>`:'IRON LEGION STRIKE <kbd>R</kbd>'}
function nearestEnemy(max=50){let best=null,dist=max;for(const e of enemies){const d=e.position.distanceTo(hero.position);if(d<dist){dist=d;best=e}}return best}
function fireWeb(){if(!started||ended||player.shot>0||player.web<5)return;player.shot=.24;player.web=Math.max(0,player.web-3.5);sound(690,.08,'triangle',.022);
  const target=nearestEnemy(24);if(!target){announce('NO TARGET IN RANGE');return}
  const a=hero.position.clone().add(new THREE.Vector3(0,1.65,0)),b=target.position.clone().add(new THREE.Vector3(0,target.userData.boss?1.3:1.05,0));const line=makeWebLine();updateLine(line,a,b);webs.push({line,life:.17});target.userData.hp--;target.userData.hitFlash=.14;target.userData.attack=Math.max(target.userData.attack,.5);sound(260,.12,'sawtooth',.025);
  if(target.userData.hp<=0) defeat(target);
}
function melee(){if(!started||ended||player.attack>0)return;player.attack=.42;player.web=Math.max(0,player.web-1);sound(170,.11,'sawtooth',.03);let hit=false;
  for(const e of [...enemies]){const to=e.position.clone().sub(hero.position);const d=to.length();to.y=0;const face=new THREE.Vector3(Math.sin(player.heading),0,Math.cos(player.heading));if(d<3.6&&face.dot(to.normalize())>.05){e.userData.hp-=2;e.userData.hitFlash=.18;hit=true;if(e.userData.hp<=0)defeat(e)}}
