}
function defeat(e){const ix=enemies.indexOf(e);if(ix<0)return;enemies.splice(ix,1);scene.remove(e);kills++;player.web=Math.min(100,player.web+12);player.hp=Math.min(100,player.hp+5);announce(kills===total?'THE CITY IS SAFE':'TARGET DOWN');sound(520,.16,'triangle',.04);if(kills>=total){endGame(true);return}spawnTimer=1.4;updateHud()}
function zip(){if(!started||ended||player.zip>0||player.web<14)return;player.zip=1.1;player.web-=14;const target=nearestEnemy(34);if(target){const dir=target.position.clone().sub(hero.position);dir.y=0;dir.normalize();player.velocity.addScaledVector(dir,18);player.velocity.y=Math.max(player.velocity.y,5.5);const line=makeWebLine(0x91f1ff);updateLine(line,hero.position.clone().add(new THREE.Vector3(0,1.6,0)),target.position.clone().add(new THREE.Vector3(0,1,0)));webs.push({line,life:.3});announce('WEB ZIP!');sound(880,.12,'sawtooth',.03)}else{player.velocity.y=9;announce('WEB ZIP — NO TARGET');sound(560,.1,'triangle') }}
function callAssist(){if(!started||ended)return;if(assistCooldown>0){announce(`IRON LEGION RECHARGING — ${Math.ceil(assistCooldown)}s`);return}assistCooldown=28;announce('IRON LEGION — ENGAGE!');sound(110,.45,'sawtooth',.055);for(const e of [...enemies]){e.userData.hp-=3;e.userData.hitFlash=.45;if(e.userData.hp<=0)defeat(e)}updateHud()}
function takeDamage(amount){if(player.invuln>0||ended)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.6;ui['damage-flash'].classList.add('hit');damageTimer=.2;sound(90,.18,'square',.04);updateHud();if(player.hp<=0)endGame(false)}
function endGame(win){ended=true;document.body.classList.remove('playing');ui['end-title'].innerHTML=win?'YOU DID<br><em>GOOD, KID.</em>':'NOT THIS<br><em>TIME.</em>';ui['end-copy'].textContent=win?'The city still has a friendly neighborhood Spider-Man. The Avengers owe you one.':`You took down ${kills} of ${total} scouts. New York needs you — try again.`;ui['end-screen'].classList.remove('hidden')}
function resetGame(){for(const e of enemies)scene.remove(e);enemies.length=0;for(const w of webs)scene.remove(w.line);webs.length=0;kills=0;spawned=0;spawnTimer=0;assistCooldown=0;player.hp=100;player.web=100;player.velocity.set(0,0,0);player.heading=0;hero.position.set(0,0,0);ended=false;started=true;ui['end-screen'].classList.add('hidden');ui['intro-screen'].classList.add('hidden');document.body.classList.add('playing');for(let i=0;i<4;i++)makeEnemy();updateHud();announce('THE INVASION HAS BEGUN')}

