ui['start-button'].addEventListener('click',resetGame);ui['restart-button'].addEventListener('click',resetGame);
ui['audio-toggle'].addEventListener('click',()=>{audio.on=!audio.on;ui['audio-toggle'].innerHTML=audio.on?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(audio.on)sound(440,.1,'sine')});
