 function makeEnemy(boss=false){const e=new THREE.Group();const armor=new THREE.MeshStandardMaterial({color:boss?0x79301d:0x4b9b8b,metalness:.58,roughness:.32,emissive:boss?0xff4a12:0x0d6252,emissiveIntensity:.75});const body=new THREE.Mesh(new THREE.IcosahedronGeometry(boss?.78:.48,1),armor);body.position.y=.9;body.castShadow=true;e.add(body);for(let n=0;n<4;n++){const a=n*Math.PI/2;const spike=new THREE.Mesh(new THREE.ConeGeometry(.12,.58,5),armor);spike.position.set(Math.sin(a)*.35,1,Math.cos(a)*.35);spike.rotation.x=Math.cos(a)*.8;spike.rotation.z=-Math.sin(a)*.8;e.add(spike)}const eye=new THREE.Mesh(new THREE.SphereGeometry(.16,8,6),new THREE.MeshBasicMaterial({color:0xff381f}));eye.position.set(0,1.04,.42);e.add(eye);const barCanvas=document.createElement('canvas');barCanvas.width=128;barCanvas.height=20;const barTexture=new THREE.CanvasTexture(barCanvas);const bar=new THREE.Sprite(new THREE.SpriteMaterial({map:barTexture,depthTest:false}));bar.position.y=2.05;bar.scale.set(1.7,.27,1);e.add(bar);const data={boss,hp:boss?160:55,maxHp:boss?160:55,phase:Math.random()*6,attack:1+Math.random(),barCtx:barCanvas.getContext('2d'),barTexture,hitFlash:0};e.userData=data;const angle=Math.random()*Math.PI*2,r=14+Math.random()*11;e.position.set(hero.position.x+Math.cos(angle)*r,.12,hero.position.z+Math.sin(angle)*r);scene.add(e);enemies.push(e);spawned++;if(boss){ui['boss-alert'].classList.add('active');setTimeout(()=>ui['boss-alert'].classList.remove('active'),2600);toast('Drop ship down! Take out the commander!')}updateHud()}

